def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dictionaries. Lists are treated atomically.
    If an entire dictionary key is added or removed, only the parent path is returned.
    """
    results = []
    _compare(before, after, "", results)
    return sorted(results)


def _compare(before, after, prefix, results):
    for key in set(before) | set(after):
        path = f"{prefix}.{key}" if prefix else key
        if key not in before:
            results.append(path)
        elif key not in after:
            results.append(path)
        else:
            b = before[key]
            a = after[key]
            if isinstance(b, dict) and isinstance(a, dict):
                _compare(b, a, path, results)
            elif b != a:
                results.append(path)
```

