def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    for item in items:
        if len(item.encode("utf-8")) > max_bytes:
            raise ValueError("item exceeds max_bytes")

    if not items:
        return []

    result = []
    current_batch = []
    current_size = 0

    for item in items:
        item_size = len(item.encode("utf-8"))
        if current_size + item_size <= max_bytes:
            current_batch.append(item)
            current_size += item_size
        else:
            result.append(current_batch)
            current_batch = [item]
            current_size = item_size

    if current_batch:
        result.append(current_batch)

    return result
```

