def admit(times, limit, window):
    if limit < 1 or window < 1:
        raise ValueError
    result = []
    accepted = deque()
    for t in times:
        while accepted and accepted[0] <= t - window:
            accepted.popleft()
        if len(accepted) < limit:
            accepted.append(t)
            result.append(True)
        else:
            result.append(False)
